import asyncio
import json
from mcp import ClientSession
from mcp.client.streamable_http import streamablehttp_client

async def main():
    async with streamablehttp_client("http://are-sidecar:8000/mcp") as (read, write, _):
        async with ClientSession(read, write) as session:
            await session.initialize()

            # Check emails from data scientists
            print("=== EMAILS FROM DATA SCIENTISTS ===")
            for email_addr in ["kritsana.wongcharee@gaia2mail.com", "aurelien.dumont@kuleuven.be", "nalinee.wongchinda@gaia2mail.com"]:
                try:
                    result = await session.call_tool("Emails__search_emails", {"query": email_addr})
                    for c in result.content:
                        if hasattr(c, 'text'):
                            print(f"  Search {email_addr}: {c.text[:500]}")
                except Exception as e:
                    print(f"  Error searching {email_addr}: {e}")
            print()

            # Check messages from data scientists
            print("=== MESSAGES FROM DATA SCIENTISTS ===")
            for name in ["Kritsana", "Aurélien", "Nalinee"]:
                try:
                    result = await session.call_tool("Messages__search", {"query": name})
                    for c in result.content:
                        if hasattr(c, 'text'):
                            data = c.text
                            print(f"  Search {name}: {data[:500]}")
                except Exception as e:
                    print(f"  Error searching {name}: {e}")
            print()

            # List recent conversations
            print("=== RECENT CONVERSATIONS ===")
            try:
                result = await session.call_tool("Messages__list_recent_conversations", {})
                for c in result.content:
                    if hasattr(c, 'text'):
                        print(c.text[:1000])
            except Exception as e:
                print(f"  Error: {e}")
            print()

            # List all emails
            print("=== ALL EMAILS ===")
            try:
                result = await session.call_tool("Emails__list_emails", {})
                for c in result.content:
                    if hasattr(c, 'text'):
                        print(c.text[:2000])
            except Exception as e:
                print(f"  Error: {e}")
            print()

asyncio.run(main())
